import{_ as e,c as l,o as s,ag as t}from"./chunks/framework.Cycwnjj0.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),o={name:"guide/changelog.md"};function r(n,i,a,u,d,g){return s(),l("div",null,[...i[0]||(i[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p><strong>2.2.3 – September, 25, 2025</strong></p><ul><li>Adds Option to edit product titles in comparison tables</li><li>Fixes Query params include with product template</li><li>Improves Cloaked URL handling and customization options</li></ul><p><strong>2.2.2 – April, 18, 2025</strong></p><ul><li>Fixes Main JavaScript file was being removed automatically on Namecheap shared hosting</li><li>Fixes Text domain loading issue with WordPress 6.8</li></ul><p><strong>2.2.1 – March, 6, 2025</strong></p><ul><li>Fixes Amazon product table loader issue</li><li>Fixes Product list render issue</li><li>Fixes Amazon product &amp; comparison table pagination issue</li><li>Fixes Unique click tracking issue</li><li>Improves Customers can add custom content under any product table item</li></ul><p><strong>2.2.0 – August, 15, 2024</strong></p><ul><li>Fixes Fetching issue of Azp Single product (gutenberg block)</li><li>Fixes Editing issue of Azp Pros and Cons (gutenberg block)</li><li>Fixes Responsive design issue of Custom Product&#39;s Grid template</li><li>Fixes Azp Single Product&#39;s Image alt tag issue</li><li>Adds Disclaimer text option for Custom products</li><li>Makes Admin sites text translatable</li><li>Improves Custom Product module, in terms of better fetching and reliability</li><li>Improves Azp block&#39;s editor</li><li>Improves Custom Products rating component</li></ul><p><strong>2.1.1 – May 30, 2024</strong></p><ul><li>Adds Button for custom multiple product card</li><li>Fixes Conflict with RankMath Plugin</li><li>Fixes Preview URL issue</li><li>Fixes Cloaked URL issue</li><li>Fixes Multi Shortcode Render issue for Custom Product</li></ul><p><strong>2.1.0 – Feb 28, 2024</strong></p><ul><li>Adds Custom product and template (Zero API)</li><li>Adds Advanced reports with click tracking</li><li>Adds Geolocation tracking</li><li>Adds Refactor UI designs</li><li>Fixes Other minor issues</li></ul><p><strong>2.0.8 – Sept 30, 2022</strong></p><ul><li>Adds shortcode size attributes</li><li>Fixes pagination break issue</li><li>Row hover color issue fix on semantic_ui table</li></ul><p><strong>2.0.7 – Oct 30, 2021</strong></p><ul><li>Adds Single product gutenberg block</li><li>Adds Call to action gutenberg block</li><li>Adds Pros and cons gutenberg block</li><li>Adds Button gutenberg block</li><li>Adds Start ratings gutenberg block</li><li>Adds Notification gutenberg block</li><li>Adds Notice gutenberg block</li><li>Fixes Comparison table word-break issue</li><li>Fixes Table edit not working issue</li><li>Fixes Amazon gutenberg blocks issues</li></ul><p><strong>2.0.6 – Aug 04, 2021</strong></p><ul><li>Fixes products table row delete issue</li></ul><p><strong>2.0.5 – Jul 17, 2021</strong></p><ul><li>Adds optional settings &quot;noindex&quot; (on meta) to prevent indexing</li><li>Adds custom hooks and filters to make custom template</li><li>Fixes page breaking(sidebar goes down) issue</li><li>Fixes frontend unused scripts issue</li><li>Fixes Cumulative Layout Shift (CLS) issue</li><li>Fixes Product table content hover issue on background</li><li>Fixes Html fields edit issue</li><li>Fixes Large product image issue</li><li>Fixes prime status issue</li><li>Fixes editor Custom button issue</li></ul><p><strong>2.0.4 – May 03, 2021</strong></p><ul><li>Adds pagination for product table</li><li>Fixes label hide issue for mobile device</li><li>Fixes Asin issue for particular products</li><li>Fixes library conflicts issue</li></ul><p><strong>2.0.3 – Apr 12, 2021</strong></p><ul><li>Fixes Api query issue</li></ul><p><strong>2.0.2 – Apr 09, 2021</strong></p><ul><li>Adds nonce validation for admin ajax</li></ul><p><strong>2.0.1 – Mar 12, 2021</strong></p><ul><li>Fixes image size issue</li></ul><p><strong>2.0.0 – Mar 12, 2021</strong></p><ul><li>Adds guten-blocks for gutenberg editor</li><li>Adds table duplicate option</li><li>Adds endpoints for custom template</li><li>Fixes comma separated discount issue</li><li>Fixes no follow issue for product templates</li><li>Fixed Php deprecated issue</li><li>Fixes border issue for product table</li><li>Fixes mobile device label issue</li><li>Fixes typo mistakes</li></ul><hr>',32)])])}const m=e(o,[["render",r]]);export{p as __pageData,m as default};
